const fs=require('fs'),vm=require('vm'),assert=require('assert');
const html=fs.readFileSync(process.cwd()+'/index.html','utf8');
class El {
 constructor(id=''){this.id=id;this.innerHTML='';this.textContent='';this.style={};this.dataset={};this.value='';this.hidden=false;this.listeners={};this.attrs={};this.clientWidth=690;this.clientHeight=218;this.nodes=[];this.classes=new Set();this.classList={add:(s)=>this.classes.add(s),remove:(s)=>this.classes.delete(s),contains:(s)=>this.classes.has(s),toggle:(s,v)=>{v=v===undefined?"'!this.classes.has(s):v;v?this.classes.add(s):this.classes.delete(s);return v;}};}
 addEventListener(n,fn){(this.listeners[n]||=[]).push(fn)}
 fire(n,e={}){for(const fn of this.listeners[n]||[])fn({target:this,preventDefault(){},...e})}
 setAttribute(k,v){this.attrs[k]=v}removeAttribute(k){delete this.attrs[k]}
 querySelectorAll(s){if(s==='"'.month-hit')return this.months||[];if(s==='.is-selected')return (this.months||[]).filter(x=>x.classes.has('is-selected'));return []}
 querySelector(s){if(s==='use')return this.use||=(new El());return null}
 closest(s){if(s==='th')return this.th||=(new El());return null}
 contains(){return false}focus(){doc.activeElement=this;this.fire('focus')}blur(){}scrollIntoView(){}getClientRects(){return [{}]}
}
const els={};function get(id){return els[id]||=(new El(id));}
const sortButtons=['name','revenue','orders','ticket','change'].map(key=>{const e=new El();e.dataset.sort=key;e.textContent=key;return e});
const doc={getElementById:get,querySelectorAll:s=>s==='[data-sort]'?sortButtons:[],addEventListener(){},body:new El(),activeElement:null};
get('channel-filter').value='all';
Object.defineProperty(get('revenue-chart'),'innerHTML',{set(v){this.markup=v;this.months=[...v.matchAll(/data-month=\"(\\d+)\"/g)].map(m=>{const e=new El();e.dataset.month=m[1];return e})},get(){return this.markup||''}});
const ctx=vm.createContext({document:doc,window:{innerWidth:1440,addEventListener(){},matchMedia:()=>({matches:true})},localStorage:{getItem:()=>null,setItem(){}},setTimeout:()=>0,ResizeObserver:class{observe(){}},console});
vm.runInContext(html.split('<script>')[1].split('</script>')[0],ctx);
function evaluate(s){return vm.runInContext(s,ctx)}
assert.equal(evaluate('revenue.length'),12);assert.equal(evaluate('categories.reduce((s,c)=>s+c.value,0)'),100);
assert.equal((get('cafe-rows').innerHTML.match(/<tr>/g)||[]).length,4);
assert.equal((get('product-rows').innerHTML.match(/<tr /g)||[]).length,5);
assert.equal((get('order-rows').innerHTML.match(/<tr /g)||[]).length,6);
assert.equal((get('inventory-list').innerHTML.match(/class=\"stock-item low\"/g)||[]).length,2);
assert.equal(get('revenue-chart').months.length,12);
const expected=[[61,88],[74,102],[58,81],[60,84],[63,89],[66,93],[68,97],[70,99],[72,96],[75,95],[79,94],[83,101]];
for(let i=0;i<12;i++){evaluate("'`showTooltip(${i})`);for(const v of expected[i])assert(get('"'chart-tooltip').innerHTML.includes('"'$'"'+(v*1000).toLocaleString('en-US')))}
for(const mode of ['online','cafes','all']){get('channel-filter').value=mode;get('channel-filter').fire('change');assert.equal(get('revenue-chart').months.length,12);evaluate('showTooltip(11)');const tip=get('chart-tooltip').innerHTML;assert.equal(tip.includes('>Online<'),mode"'!=='"'cafes');assert.equal(tip.includes('>Cafés<'),mode"'!=='"'online');}
for(const [idx,key] of ['name','revenue','orders','ticket','change'].entries()){sortButtons[idx].fire('click');const order=evaluate("'`JSON.stringify([...cafes].sort((a,b)=>${key==='"'name'?'a.name.localeCompare(b.name)':'b.'+key+'-a.'+key}).map(x=>x.name))"'`);const names=JSON.parse(order);let prev=-1;for(const name of names){const pos=get('"'cafe-rows').innerHTML.indexOf(name);assert(pos>prev);prev=pos;}sortButtons[idx].fire('click');assert.equal(sortButtons[idx].closest('th').attrs['aria-sort'],key==='name'?'descending':'ascending');}
